import {trackFX} from './beat-mixer.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createMixerEditor(root,{state,changed,master,setMaster,meters}){let lastMeter=0;const q=s=>root.querySelector(s);function render(){root.innerHTML=`<h2>Mixer · shape the whole song</h2><p>Play from Playlist or Mixer to hear all tracks. Peak/RMS meters measure real channel audio after EQ/effects and track gain/pan, before master gain. Master meter is after master gain; red means a sampled peak reaches 0 dBFS. It is not a true-peak or loudness meter.</p><label>Master volume<input id="mxMaster" type="range" min="0" max="1" step=".01" value="${master()}"></label><output id="mxMasterMeter">Master idle</output><div class="mx-channels">${state().tracks.map(t=>`<section class="mx-channel"><h3>${esc(t.name)}</h3><output data-mx-meter="${esc(t.id)}">Idle</output>${[['volume','Volume',0,2,.01,t.volume],['pan','Pan',-1,1,.01,t.pan],['low','Low EQ · dB',-12,12,1,trackFX(t).low],['mid','Mid EQ · dB',-12,12,1,trackFX(t).mid],['high','High EQ · dB',-12,12,1,trackFX(t).high],['delay','Delay',0,.7,.05,trackFX(t).delay],['reverb','Reverb',0,.7,.05,trackFX(t).reverb]].map(([key,name,min,max,step,value])=>`<label>${name}<input data-mx-id="${esc(t.id)}" data-mx-field="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><output>${value}</output></label>`).join('')}${['mute','solo'].map(k=>`<label><input type="checkbox" data-mx-id="${esc(t.id)}" data-mx-field="${k}" ${t[k]?'checked':''}>${k}</label>`).join('')}</section>`).join('')}</div>`;q('#mxMaster').oninput=e=>setMaster(+e.target.value);root.querySelectorAll('[data-mx-field]').forEach(el=>el.onchange=()=>{const t=state().tracks.find(t=>t.id===el.dataset.mxId),k=el.dataset.mxField;if(['low','mid','high','delay','reverb'].includes(k))t.fx={...trackFX(t),[k]:+el.value};else t[k]=el.type==='checkbox'?el.checked:+el.value;changed();render();});}
 const text=m=>`${m.peak>=1?'CLIP · ':''}peak ${m.peak>0?(20*Math.log10(m.peak)).toFixed(1):'−∞'} dBFS · RMS ${m.rms>0?(20*Math.log10(m.rms)).toFixed(1):'−∞'} dBFS`;
 return{render,update(){if(root.hidden||performance.now()-lastMeter<80)return;lastMeter=performance.now();const data=meters();root.querySelectorAll('[data-mx-meter]').forEach(el=>{const m=data.tracks.get(el.dataset.mxMeter)||{peak:0,rms:0};el.textContent=text(m);el.classList.toggle('clipping',m.peak>=1);});const el=q('#mxMasterMeter');if(el){el.textContent='Master '+text(data.master);el.classList.toggle('clipping',data.master.peak>=1);}},dispose(){root.replaceChildren();}};
}
